(4067521, 583342, 15711, '<td valign="top">Reminiscent of a Monet for sure.  I really think that yellow border hurts it.</td>', 'Reminiscent of a Monet for sure.  I really think that yellow border hurts it.', '2007-09-07 01:04:51.000000', NULL, 1),
(4067523, 583269, 64670, '<td valign="top">I think the tongue is really funny - I love the way it waves.</td>', 'I think the tongue is really funny - I love the way it waves.', '2007-09-07 01:05:12.000000', NULL, 1),
(4067525, 583086, 46177, '<td valign="top">I can''t even begin to tell you how much I love this, I only wish I could give you a 20 as it is you will have to settle for a 10 and a fav.</td>', 'I can''t even begin to tell you how much I love this, I only wish I could give you a 20 as it is you will have to settle for a 10 and a fav.', '2007-09-07 01:05:40.000000', NULL, 1),
(4067532, 582092, 74559, '<td valign="top">Breathtakingly beautiful! So delicate yet bold, soft yet defined, muted yet bright... This is truly a work of art!</td>', 'Breathtakingly beautiful! So delicate yet bold, soft yet defined, muted yet bright... This is truly a work of art!', '2007-09-07 01:06:52.000000', NULL, 1),
(4067533, 582251, 64670, '<td valign="top">I think less vibrant colors may have worked well in this image.</td>', 'I think less vibrant colors may have worked well in this image.', '2007-09-07 01:06:53.000000', NULL, 1),
(4067536, 583204, 15711, '<td valign="top">Really reminiscent of Monet''s Giverny.</td>', 'Really reminiscent of Monet''s Giverny.', '2007-09-07 01:07:23.000000', NULL, 1),
