(4067627, 583086, 17203, '<td valign="top">I don''t know if this is a PS filter or not, but the effect is beautiful. One of the rare instances where the effect actually compliments the image. Very impressive. 10</td>', 'I don''t know if this is a PS filter or not, but the effect is beautiful. One of the rare instances where the effect actually compliments the image. Very impressive. 10', '2007-09-07 01:23:26.000000', NULL, 1),
(4067644, 582956, 17203, '<td valign="top">Love the brushstrokes, and I cen certainy appreciate the effort that must have gone into this. The centered composition is a little static for my taste, but the colors and lighting work well. Nicely done!</td>', 'Love the brushstrokes, and I cen certainy appreciate the effort that must have gone into this. The centered composition is a little static for my taste, but the colors and lighting work well. Nicely done!', '2007-09-07 01:26:04.000000', NULL, 1),
