(4069100, 582924, 68256, '<td valign="top">Very classic indeed.  Filter or no filter it wouldn''t matter with this great composition.  Very well done in both impressionistic style and aesthetic beauty.</td>', 'Very classic indeed.  Filter or no filter it wouldn''t matter with this great composition.  Very well done in both impressionistic style and aesthetic beauty.', '2007-09-07 13:18:26.000000', NULL, 1),
(4069107, 583005, 68256, '<td valign="top">Ahh the classic sale boats.  Very well done in both style and composition.  There seems to be patches of water that look different than the rest though, like in the foreground and to the right of the rear boat.</td>', 'Ahh the classic sale boats.  Very well done in both style and composition.  There seems to be patches of water that look different than the rest though, like in the foreground and to the right of the rear boat.', '2007-09-07 13:21:40.000000', NULL, 1),
(4069120, 580803, 68256, '<td valign="top">Lovely study in impressionism.  The few blown spots on the fruit are a little distracting considering the "painting" effect, but the overall lighting isn''t bad.  8</td>', 'Lovely study in impressionism.  The few blown spots on the fruit are a little distracting considering the "painting" effect, but the overall lighting isn''t bad.  8', '2007-09-07 13:25:51.000000', NULL, 1),
(4069134, 582427, 68256, '<td valign="top">I love this composition, the leading lines are just wonderful and the water is so "impressionstic".  I don''t even mind the mixing of warm and cool tones as it works well here.  I know including a color from within the photo for the border is a great way to tie it all together but I think I would have prefered a simple black border, that is a personal preference and doesn''t effect my voting.  8</td>', 'I love this composition, the leading lines are just wonderful and the water is so "impressionstic".  I don''t even mind the mixing of warm and cool tones as it works well here.  I know including a color from within the photo for the border is a great way to tie it all together but I think I would have prefered a simple black border, that is a personal preference and doesn''t effect my voting.  8', '2007-09-07 13:29:14.000000', NULL, 1),
(4069135, 581300, 68514, '<td valign="top">This is not impressionism.</td>', 'This is not impressionism.', '2007-09-07 13:29:27.000000', NULL, 1),
(4069137, 582957, 62318, '<td valign="top">Spectacular shot. The color palette is amazing. Good composition, wonderful shadows.</td>', 'Spectacular shot. The color palette is amazing. Good composition, wonderful shadows.', '2007-09-07 13:29:37.000000', NULL, 1),
(4069140, 583337, 74979, '<td valign="top">almost pointalistic effect, sky came out the best</td>', 'almost pointalistic effect, sky came out the best', '2007-09-07 13:30:05.000000', NULL, 1);
