(4070149, 583337, 54446, '<td valign="top">An obviously unlevel horizon.... with the water appearing to be ready to flush out the left side of the photo.... is a problem.  Otherwise, I like the image and the treatment.  (6)</td>', 'An obviously unlevel horizon.... with the water appearing to be ready to flush out the left side of the photo.... is a problem.  Otherwise, I like the image and the treatment.  (6)', '2007-09-07 19:19:16.000000', NULL, 1),
(4070151, 582921, 326, '<td valign="top">NICE JOB. THE GREEN LINES IN THE WATER IS A VERY NICE TOUCH TO THIS.</td>', 'NICE JOB. THE GREEN LINES IN THE WATER IS A VERY NICE TOUCH TO THIS.', '2007-09-07 19:20:25.000000', NULL, 1),
(4070153, 583005, 80096, '<td valign="top">excellent 7</td>', 'excellent 7', '2007-09-07 19:21:02.000000', NULL, 1),
(4070156, 583263, 77196, '<td valign="top">Your horizon is in almost the exact center of your photo. A nice shot with strong realism.</td>', 'Your horizon is in almost the exact center of your photo. A nice shot with strong realism.', '2007-09-07 19:21:49.000000', NULL, 1),
(4070157, 583186, 326, '<td valign="top">THIS LOOKS LIKE A PLACE I WOULD LOVE TO EXPLORE. NICE JOB.</td>', 'THIS LOOKS LIKE A PLACE I WOULD LOVE TO EXPLORE. NICE JOB.', '2007-09-07 19:21:59.000000', NULL, 1),
