(4070164, 582092, 62671, '<td valign="top">Love the colors.</td>', 'Love the colors.', '2007-09-07 19:22:58.000000', NULL, 1),
(4070169, 581851, 62671, '<td valign="top">A great natural way to create strokes of color.  Very well thought out.</td>', 'A great natural way to create strokes of color.  Very well thought out.', '2007-09-07 19:24:06.000000', NULL, 1),
(4070170, 580938, 62671, '<td valign="top">great job of color, technique, and composition.</td>', 'great job of color, technique, and composition.', '2007-09-07 19:24:32.000000', NULL, 1),
