(4070180, 582190, 62671, '<td valign="top">A lovely watercolor image.  Colors are dreamy!</td>', 'A lovely watercolor image.  Colors are dreamy!', '2007-09-07 19:27:13.000000', NULL, 1),
(4070181, 583147, 326, '<td valign="top">THIS WORKS WELL! NICE JOB.</td>', 'THIS WORKS WELL! NICE JOB.', '2007-09-07 19:27:32.000000', NULL, 1),
