(4070186, 583282, 62671, '<td valign="top">This is one of my favorite of the challenge.  Lovely lighting and subject matter.  My choice for the red.</td>', 'This is one of my favorite of the challenge.  Lovely lighting and subject matter.  My choice for the red.', '2007-09-07 19:29:24.000000', NULL, 1),
(4070187, 582245, 326, '<td valign="top">COOL! AT FIRST I THOUGHT THIS WAS A PICTURE OF FISH. NICE JOB.</td>', 'COOL! AT FIRST I THOUGHT THIS WAS A PICTURE OF FISH. NICE JOB.', '2007-09-07 19:29:32.000000', NULL, 1),
(4070188, 583333, 326, '<td valign="top">LOVELY WORK. SO SOFT. NICE JOB.</td>', 'LOVELY WORK. SO SOFT. NICE JOB.', '2007-09-07 19:30:32.000000', NULL, 1),
(4070192, 583249, 326, '<td valign="top">WOW... THIS IS SO COLORFUL AND DIFFERENT. GOOD JOB.</td>', 'WOW... THIS IS SO COLORFUL AND DIFFERENT. GOOD JOB.', '2007-09-07 19:31:19.000000', NULL, 1),
