INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4070194, 583086, 62671, '<td valign="top">Lovely! I''m choosing this one to be my yellow.</td>', 'Lovely! I''m choosing this one to be my yellow.', '2007-09-07 19:32:46.000000', NULL, 1),
(4070197, 583282, 326, '<td valign="top">THIS IS AWESOME! GREAT JOB!</td>', 'THIS IS AWESOME! GREAT JOB!', '2007-09-07 19:34:52.000000', NULL, 1),
(4070198, 583218, 83080, '<td valign="top">I like your creative interpretation.  It''s also such a refreshingly crisp shot compared to the stricter impressionism approach.</td>', 'I like your creative interpretation.  It''s also such a refreshingly crisp shot compared to the stricter impressionism approach.', '2007-09-07 19:34:53.000000', NULL, 1),
(4070212, 582956, 326, '<td valign="top">VERY NICE WORK.</td>', 'VERY NICE WORK.', '2007-09-07 19:38:43.000000', NULL, 1),
(4070213, 581101, 326, '<td valign="top">WONDERFUL JOB! SO PRETTY.</td>', 'WONDERFUL JOB! SO PRETTY.', '2007-09-07 19:39:21.000000', NULL, 1),
(4070215, 583292, 83080, '<td valign="top">Oh my, the amount of blur makes this shot difficult to look at.  Still, I apreciate the elements that make this seem like an impressionistic setting</td>', 'Oh my, the amount of blur makes this shot difficult to look at.  Still, I apreciate the elements that make this seem like an impressionistic setting', '2007-09-07 19:39:53.000000', NULL, 1),
(4070226, 582821, 13207, '<td valign="top">Excellent colour in this shot, one of my favorites for this challenge so far.</td>', 'Excellent colour in this shot, one of my favorites for this challenge so far.', '2007-09-07 19:43:12.000000', NULL, 1),
(4070228, 580875, 13207, '<td valign="top">Beautiful - great reflection and the post-processing is just enough to give it the ''impressionism'' look without losing the sharp detail.</td>', 'Beautiful - great reflection and the post-processing is just enough to give it the ''impressionism'' look without losing the sharp detail.', '2007-09-07 19:44:00.000000', NULL, 1),
(4070229, 582924, 13207, '<td valign="top">Beautiful - and what a perfect model for a shot like this.</td>', 'Beautiful - and what a perfect model for a shot like this.', '2007-09-07 19:44:44.000000', NULL, 1),
(4070237, 580273, 83080, '<td valign="top">Ahhh, a picture I can look at :)  Nice job using water as a natural impressionism filter.</td>', 'Ahhh, a picture I can look at :)  Nice job using water as a natural impressionism filter.', '2007-09-07 19:46:38.000000', NULL, 1),
(4070259, 580563, 83080, '<td valign="top">That''s excellent.  I love that there''s clearly a good photo here and not just impressionism FX.  I might have cropped out more of the white from the top, but that''s just my unqualified opinion.</td>', 'That''s excellent.  I love that there''s clearly a good photo here and not just impressionism FX.  I might have cropped out more of the white from the top, but that''s just my unqualified opinion.', '2007-09-07 19:52:44.000000', NULL, 1),
(4070265, 583342, 83080, '<td valign="top">Nice capture conveying impressionism without overworking the FX</td>', 'Nice capture conveying impressionism without overworking the FX', '2007-09-07 19:53:47.000000', NULL, 1),
(4070283, 582064, 83080, '<td valign="top">Ah Ha!  Love it!  This is what I decided to do too.  I hope the voters appreciate this approach with the ''natural'' impressionism filter of the water reflection.  Your colors &amp; depth are much better than I was able to capture though. My favorite by a long shot. -10-</td>', 'Ah Ha!  Love it!  This is what I decided to do too.  I hope the voters appreciate this approach with the ''natural'' impressionism filter of the water reflection.  Your colors & depth are much better than I was able to capture though. My favorite by a long shot. -10-', '2007-09-07 20:00:03.000000', NULL, 1),
(4070297, 581851, 83080, '<td valign="top">Great shot and great use of the water filter.</td>', 'Great shot and great use of the water filter.', '2007-09-07 20:04:32.000000', NULL, 1),
(4070309, 582921, 83080, '<td valign="top">Excellent use of the reflection!  This is just like some Monet pictures I saw researching for this challenge.  I looked for a good shot like this one, but had to settle for another reflection idea.  Clearly one of the best put forward for this challenge.  Thanks.  -10-</td>', 'Excellent use of the reflection!  This is just like some Monet pictures I saw researching for this challenge.  I looked for a good shot like this one, but had to settle for another reflection idea.  Clearly one of the best put forward for this challenge.  Thanks.  -10-', '2007-09-07 20:09:34.000000', NULL, 1),
(4070413, 580560, 76217, '<td valign="top">Great shot, composition, interpretation, and title.<br/>I''d be surprised if this shot scores well. 8</td>', 'Great shot, composition, interpretation, and title.I''d be surprised if this shot scores well. 8', '2007-09-07 20:47:24.000000', NULL, 1),
(4070432, 582704, 76217, '<td valign="top">Too much PP filtering for DPC. I think its well done however.</td>', 'Too much PP filtering for DPC. I think its well done however.', '2007-09-07 20:52:49.000000', NULL, 1),
(4070436, 583346, 67152, '<td valign="top">the colors and textures are pretty good here</td>', 'the colors and textures are pretty good here', '2007-09-07 20:54:45.000000', NULL, 1),
(4070440, 579965, 76217, '<td valign="top">An honest attempt at what I interpret as photographic impressionism. I''ll bet your score sucks right now. 7</td>', 'An honest attempt at what I interpret as photographic impressionism. I''ll bet your score sucks right now. 7', '2007-09-07 20:55:42.000000', NULL, 1),
(4070455, 581096, 67152, '<td valign="top">love the glow and the soft colors</td>', 'love the glow and the soft colors', '2007-09-07 20:59:32.000000', NULL, 1),
(4070456, 583087, 83758, '<td valign="top">One of the best. Colour, composition, light, texture, style... has it all. I really do not think you (or anyone else) could improve upon this. 10 in my books.</td>', 'One of the best. Colour, composition, light, texture, style... has it all. I really do not think you (or anyone else) could improve upon this. 10 in my books.', '2007-09-07 20:59:56.000000', NULL, 1),
(4070457, 582190, 83758, '<td valign="top">At first glance, there is little that is exceptional about this work except that works! It is a good composition, well lit, great post production and looks like it was painted by a classic impressionist... well done. I really like... one of the best.</td>', 'At first glance, there is little that is exceptional about this work except that works! It is a good composition, well lit, great post production and looks like it was painted by a classic impressionist... well done. I really like... one of the best.', '2007-09-07 21:00:12.000000', NULL, 1),
(4070459, 580408, 83758, '<td valign="top">Good colour, lighting, cropping, subject and nice post production... I would hang it on my wall!</td>', 'Good colour, lighting, cropping, subject and nice post production... I would hang it on my wall!', '2007-09-07 21:00:28.000000', NULL, 1),
(4070460, 580875, 83758, '<td valign="top">Impressionist and post modernist in one shot... well done. Simple subject with good post production... I would have cropped the sky tighter and shown a little more water to make it a more powerful composition, but that is being picky. Nice work.</td>', 'Impressionist and post modernist in one shot... well done. Simple subject with good post production... I would have cropped the sky tighter and shown a little more water to make it a more powerful composition, but that is being picky. Nice work.', '2007-09-07 21:00:50.000000', NULL, 1),
(4070462, 581106, 76217, '<td valign="top">Nice attempt. I think I would appreciate the photo more w/o the girl in jeans and a tank top. Kind of breaks the spell.</td>', 'Nice attempt. I think I would appreciate the photo more w/o the girl in jeans and a tank top. Kind of breaks the spell.', '2007-09-07 21:01:10.000000', NULL, 1),
(4070464, 582190, 67152, '<td valign="top">love the light and the glow created in this image</td>', 'love the light and the glow created in this image', '2007-09-07 21:01:27.000000', NULL, 1),
(4070465, 582777, 83758, '<td valign="top">A modern VG. Well done.</td>', 'A modern VG. Well done.', '2007-09-07 21:01:58.000000', NULL, 1),
(4070466, 583147, 83758, '<td valign="top">Not your average photo and therefore not your average mark. A bold attempt.</td>', 'Not your average photo and therefore not your average mark. A bold attempt.', '2007-09-07 21:02:12.000000', NULL, 1),
(4070468, 580822, 83758, '<td valign="top">Nice subject and well framed. Colours are typical of some of the impressionists. The post production is excellent... all in all a nice work.</td>', 'Nice subject and well framed. Colours are typical of some of the impressionists. The post production is excellent... all in all a nice work.', '2007-09-07 21:02:26.000000', NULL, 1),
(4070469, 582200, 81342, '<td valign="top">Love this picture. Kind of missing the impressionist part, but great shot anyways.</td>', 'Love this picture. Kind of missing the impressionist part, but great shot anyways.', '2007-09-07 21:02:34.000000', NULL, 1),
(4070471, 582251, 83758, '<td valign="top">I think that the post production produces a good impressionistic work, however, I think the composition would have been strengthened significantly by the couple walking toward the focal point rather than sitting partially obscured. Nonetheless a good work.</td>', 'I think that the post production produces a good impressionistic work, however, I think the composition would have been strengthened significantly by the couple walking toward the focal point rather than sitting partially obscured. Nonetheless a good work.', '2007-09-07 21:02:46.000000', NULL, 1),
(4070473, 583290, 76217, '<td valign="top">Yup, Broccoli, that was my first impression. 7</td>', 'Yup, Broccoli, that was my first impression. 7', '2007-09-07 21:03:04.000000', NULL, 1),
(4070475, 583182, 83758, '<td valign="top">Nice post production and a modern subject that lends itself well to the impressionist treatment. The shadow leading to the bowl is a distraction and the placement of the bowl in the central axis detracts from making it an excellent work. Nice colours and tonal range... all in all, well worth the 8.</td>', 'Nice post production and a modern subject that lends itself well to the impressionist treatment. The shadow leading to the bowl is a distraction and the placement of the bowl in the central axis detracts from making it an excellent work. Nice colours and tonal range... all in all, well worth the 8.', '2007-09-07 21:03:22.000000', NULL, 1),
(4070476, 583272, 67152, '<td valign="top">excellent use of color and light</td>', 'excellent use of color and light', '2007-09-07 21:03:28.000000', NULL, 1),
(4070479, 582088, 83758, '<td valign="top">Quite Monet... good effort.</td>', 'Quite Monet... good effort.', '2007-09-07 21:03:55.000000', NULL, 1),
(4070480, 581473, 83758, '<td valign="top">Nice work, except the horse is going in the wrong direction.</td>', 'Nice work, except the horse is going in the wrong direction.', '2007-09-07 21:04:15.000000', NULL, 1),
(4070483, 582821, 76217, '<td valign="top">Too bright and neon like for my taste.</td>', 'Too bright and neon like for my taste.', '2007-09-07 21:05:00.000000', NULL, 1),
(4070487, 580786, 67152, '<td valign="top">nice technigue to focus our sight on the lady - i really like this one</td>', 'nice technigue to focus our sight on the lady - i really like this one', '2007-09-07 21:05:45.000000', NULL, 1),
(4070489, 581863, 67152, '<td valign="top">the subject matter is a pretty good choice but the light is really flat and does not display much of the excellent light I think of when I think impressionism...</td>', 'the subject matter is a pretty good choice but the light is really flat and does not display much of the excellent light I think of when I think impressionism...', '2007-09-07 21:07:04.000000', NULL, 1),
(4070491, 583210, 67152, '<td valign="top">very cool image - rather 21st century approach to impressionism</td>', 'very cool image - rather 21st century approach to impressionism', '2007-09-07 21:07:31.000000', NULL, 1),
(4070493, 582200, 76217, '<td valign="top">Nice. Getting any over sharpened comments? 7</td>', 'Nice. Getting any over sharpened comments? 7', '2007-09-07 21:07:43.000000', NULL, 1),
(4070496, 583222, 67152, '<td valign="top">i like the background - very cool flow but the deer is not very attractive to me here with all the blur</td>', 'i like the background - very cool flow but the deer is not very attractive to me here with all the blur', '2007-09-07 21:08:18.000000', NULL, 1),
(4070502, 582821, 67152, '<td valign="top">this is just so well done - the colors so vibrant and the lines so appealing - a work of art</td>', 'this is just so well done - the colors so vibrant and the lines so appealing - a work of art', '2007-09-07 21:09:34.000000', NULL, 1),
(4070505, 580803, 67152, '<td valign="top">nice still life - pretty well done with the filters</td>', 'nice still life - pretty well done with the filters', '2007-09-07 21:09:54.000000', NULL, 1),
(4070508, 582190, 76217, '<td valign="top">Great balance between photo and processing. 8</td>', 'Great balance between photo and processing. 8', '2007-09-07 21:10:52.000000', NULL, 1),
(4070514, 580408, 67152, '<td valign="top">love this - the colors and composition and lighting really give me the feel of impressionism</td>', 'love this - the colors and composition and lighting really give me the feel of impressionism', '2007-09-07 21:16:03.000000', NULL, 1),
(4070524, 581863, 76217, '<td valign="top">Your title is horrible. Let the picture speak for itself.</td>', 'Your title is horrible. Let the picture speak for itself.', '2007-09-07 21:21:47.000000', NULL, 1),
(4070525, 582716, 76217, '<td valign="top">Over the top.</td>', 'Over the top.', '2007-09-07 21:22:36.000000', NULL, 1),
(4070599, 583204, 50641, '<td valign="top">Classic subject. Good thinking, I forgot about glow. I like the white glow, but one thing that might be fun would be to use a gold glow on this. If you have PS just change the top paint color to gold before you do a diffuse glow.  Best of luck.</td>', 'Classic subject. Good thinking, I forgot about glow. I like the white glow, but one thing that might be fun would be to use a gold glow on this. If you have PS just change the top paint color to gold before you do a diffuse glow.  Best of luck.', '2007-09-07 21:57:59.000000', NULL, 1),
(4070601, 580450, 50641, '<td valign="top">I love them turkey vultures.  Nice effect.</td>', 'I love them turkey vultures.  Nice effect.', '2007-09-07 21:58:24.000000', NULL, 1),
(4070613, 581442, 50641, '<td valign="top">Great tires! Nicely processed. Frame feels a teeny bit heavy for this?</td>', 'Great tires! Nicely processed. Frame feels a teeny bit heavy for this?', '2007-09-07 22:00:48.000000', NULL, 1),
(4070626, 582956, 50641, '<td valign="top">Great idea.  Might pump up the sat as you have a wonderful color combo there.</td>', 'Great idea.  Might pump up the sat as you have a wonderful color combo there.', '2007-09-07 22:03:25.000000', NULL, 1),
(4070631, 581230, 50641, '<td valign="top">Great title and nice light.</td>', 'Great title and nice light.', '2007-09-07 22:04:06.000000', NULL, 1),
(4070636, 581300, 50641, '<td valign="top">Remarkable.</td>', 'Remarkable.', '2007-09-07 22:04:42.000000', NULL, 1),
(4070638, 580419, 50641, '<td valign="top">Good idea!</td>', 'Good idea!', '2007-09-07 22:04:58.000000', NULL, 1),
(4070645, 579626, 3306, '<td valign="top">Beautiful arrangement. Well done.</td>', 'Beautiful arrangement. Well done.', '2007-09-07 22:06:50.000000', NULL, 1),
(4070649, 583207, 50641, '<td valign="top">Yes, it could be a Pineapple photo.  Great comp and lighting.</td>', 'Yes, it could be a Pineapple photo.  Great comp and lighting.', '2007-09-07 22:07:04.000000', NULL, 1),
(4070654, 583003, 50641, '<td valign="top">Nifty.</td>', 'Nifty.', '2007-09-07 22:07:27.000000', NULL, 1),
(4070655, 582710, 3306, '<td valign="top">Simple and attractive.</td>', 'Simple and attractive.', '2007-09-07 22:07:40.000000', NULL, 1),
(4070660, 580875, 3306, '<td valign="top">You have really captured the essence of this challenge. Beautiful work.</td>', 'You have really captured the essence of this challenge. Beautiful work.', '2007-09-07 22:08:27.000000', NULL, 1),
(4070663, 582453, 3306, '<td valign="top">Love the colors. Good job.</td>', 'Love the colors. Good job.', '2007-09-07 22:09:08.000000', NULL, 1),
(4070813, 583237, 41675, '<td valign="top">A little dark overall, but a nice image none the less. Good use of PS filters. I like the sky.</td>', 'A little dark overall, but a nice image none the less. Good use of PS filters. I like the sky.', '2007-09-07 22:50:52.000000', NULL, 1),
(4070820, 583277, 41675, '<td valign="top">Hmm, my first instinct when I saw your image was, nice abstract. I''m not sure it fits my personal idea of impressionism, yet I like the overall softness. Good tonal range of greens too.</td>', 'Hmm, my first instinct when I saw your image was, nice abstract. I''m not sure it fits my personal idea of impressionism, yet I like the overall softness. Good tonal range of greens too.', '2007-09-07 22:52:23.000000', NULL, 1),
(4070826, 583076, 41675, '<td valign="top">The background is a bit busy and distracting for me, but I really like the lighting on the glass of tea.</td>', 'The background is a bit busy and distracting for me, but I really like the lighting on the glass of tea.', '2007-09-07 22:53:17.000000', NULL, 1),
(4070832, 583295, 41675, '<td valign="top">For me, its a little impressionistic, but not quite enough. My favorite part is the bottom third of your photo. I like the white stones - they provide a good contrast to all the green.</td>', 'For me, its a little impressionistic, but not quite enough. My favorite part is the bottom third of your photo. I like the white stones - they provide a good contrast to all the green.', '2007-09-07 22:55:11.000000', NULL, 1),
(4070840, 583222, 41675, '<td valign="top">Interesting image. My eyes keep going back to that front leg. The blur makes it look kind of bell-shaped. I also wish all of the hooves were showing, rather than being cut off.</td>', 'Interesting image. My eyes keep going back to that front leg. The blur makes it look kind of bell-shaped. I also wish all of the hooves were showing, rather than being cut off.', '2007-09-07 22:57:28.000000', NULL, 1),
(4070841, 583006, 41675, '<td valign="top">Overall its a pretty picture.  I much prefer the right half to the left half - its more interesting to me.</td>', 'Overall its a pretty picture.  I much prefer the right half to the left half - its more interesting to me.', '2007-09-07 22:58:29.000000', NULL, 1),
(4070846, 583329, 41675, '<td valign="top">For me, the very thick black border is very overwhelming to the softness of the baby.</td>', 'For me, the very thick black border is very overwhelming to the softness of the baby.', '2007-09-07 22:59:28.000000', NULL, 1),
(4070853, 583339, 41675, '<td valign="top">Impressionistic or bokeh? Hmmm...It''s a very pretty image either way.</td>', 'Impressionistic or bokeh? Hmmm...It''s a very pretty image either way.', '2007-09-07 23:03:29.000000', NULL, 1),
(4070854, 583150, 41675, '<td valign="top">Nice composition and lighting. I like it.</td>', 'Nice composition and lighting. I like it.', '2007-09-07 23:03:55.000000', NULL, 1),
(4070856, 583151, 41675, '<td valign="top">A bit over done for my personal notion of impressionism. I don''t mind the building, its the sky that I''m not crazy about.</td>', 'A bit over done for my personal notion of impressionism. I don''t mind the building, its the sky that I''m not crazy about.', '2007-09-07 23:04:36.000000', NULL, 1),
(4070859, 583269, 41675, '<td valign="top">The filter effect upon the tongue makes me laugh. It looks like Prince has a square tongue! Lol I like the impressionistic impression though - good job and good luck in the challenge.</td>', 'The filter effect upon the tongue makes me laugh. It looks like Prince has a square tongue! Lol I like the impressionistic impression though - good job and good luck in the challenge.', '2007-09-07 23:05:36.000000', NULL, 1),
(4070867, 583111, 41675, '<td valign="top">For me, I''m distracted by the blue in the lower left quadrant, in front of the tree. I like the light reflecting on the water though.</td>', 'For me, I''m distracted by the blue in the lower left quadrant, in front of the tree. I like the light reflecting on the water though.', '2007-09-07 23:06:47.000000', NULL, 1),
(4070869, 583336, 41675, '<td valign="top">Definitely gives impressionistic, maybe a bit overboard, but not badd. I like the background contrast against the color of the flowers.</td>', 'Definitely gives impressionistic, maybe a bit overboard, but not badd. I like the background contrast against the color of the flowers.', '2007-09-07 23:07:45.000000', NULL, 1),
(4070870, 583207, 74821, '<td valign="top">Very nice image.  I''m adding it to my favorites.  Unfortunately I have to deduct points because I think it does not meet the challenge.</td>', 'Very nice image.  I''m adding it to my favorites.  Unfortunately I have to deduct points because I think it does not meet the challenge.', '2007-09-07 23:08:14.000000', NULL, 1),
