(4074791, 582906, 81362, '<td valign="top">Wonderful simplicity and study on the play of light in an everyday setting. One of my top ten for the challenge.</td>', 'Wonderful simplicity and study on the play of light in an everyday setting. One of my top ten for the challenge.', '2007-09-09 12:10:11.000000', NULL, 1),
(4074794, 582245, 81362, '<td valign="top">Playful, colorful, engergetic, and crative. Not a copy of an imprssionist work, but in the spirit of the movement.  I like it a lot.</td>', 'Playful, colorful, engergetic, and crative. Not a copy of an imprssionist work, but in the spirit of the movement.  I like it a lot.', '2007-09-09 12:12:05.000000', NULL, 1),
