(4074938, 582922, 51538, '<td valign="top">Nice choice of subject and treatment.  It works well to say, "impressionism." 7.</td>', 'Nice choice of subject and treatment.  It works well to say, "impressionism." 7.', '2007-09-09 13:36:42.000000', NULL, 1),
(4075109, 580961, 39536, '<td valign="top">This is what I had in mind when I saw the topic "Impressionism." Sure, there are lots of ways to get an imressionistic look with digital imaging, but the really good photographers are going to be looking for opportunities like this to create an imressionistic scene in the real world. This is nicley done.</td>', 'This is what I had in mind when I saw the topic "Impressionism." Sure, there are lots of ways to get an imressionistic look with digital imaging, but the really good photographers are going to be looking for opportunities like this to create an imressionistic scene in the real world. This is nicley done.', '2007-09-09 14:57:10.000000', NULL, 1),
(4075120, 583292, 73250, '<td valign="top">I like the subject...but, for me it needs to be a little more clear and have more texture.</td>', 'I like the subject...but, for me it needs to be a little more clear and have more texture.', '2007-09-09 15:00:26.000000', NULL, 1),
(4075123, 582795, 73250, '<td valign="top">I feel like the focal point is missing...the only thing that comes to mind would be the red brick, that''s where my eye is drawn.</td>', 'I feel like the focal point is missing...the only thing that comes to mind would be the red brick, that''s where my eye is drawn.', '2007-09-09 15:01:37.000000', NULL, 1),
