(4075924, 583290, 73250, '<td valign="top">Interesting effect...I like the look and the vibrant color.</td>', 'Interesting effect...I like the look and the vibrant color.', '2007-09-09 22:22:35.000000', NULL, 1),
(4075929, 583217, 73250, '<td valign="top">The effect has been applied well to this image. I like the composition. I would have liked to see the saturation in the green bumped a bit.</td>', 'The effect has been applied well to this image. I like the composition. I would have liked to see the saturation in the green bumped a bit.', '2007-09-09 22:25:20.000000', NULL, 1),
(4077479, 583271, 73250, '<td valign="top">I like the texture, but would have liked to see the color pushed a little.</td>', 'I like the texture, but would have liked to see the color pushed a little.', '2007-09-10 09:42:19.000000', NULL, 1),
(4077486, 581508, 73250, '<td valign="top">Interesting take on the challenge. I think that the effect would have worked better if the focal point was so centered.</td>', 'Interesting take on the challenge. I think that the effect would have worked better if the focal point was so centered.', '2007-09-10 09:43:43.000000', NULL, 1),
(4077490, 582971, 73250, '<td valign="top">I like the effect and the texture. Nice comp and vibrant colors.</td>', 'I like the effect and the texture. Nice comp and vibrant colors.', '2007-09-10 09:44:35.000000', NULL, 1),
(4077492, 583336, 73250, '<td valign="top">I think that your interpretation of impressionism is nice. I like the colors. I think I would have liked more to it...another component in the image...maybe, a table. Just a thought.</td>', 'I think that your interpretation of impressionism is nice. I like the colors. I think I would have liked more to it...another component in the image...maybe, a table. Just a thought.', '2007-09-10 09:44:44.000000', NULL, 1),
(4077499, 581226, 73250, '<td valign="top">My feeling about impressionism is that your are able to recognize the subject...and there is a lot of texture and brush strokes. I think that the soft blur doesn''t say impressionism to me.</td>', 'My feeling about impressionism is that your are able to recognize the subject...and there is a lot of texture and brush strokes. I think that the soft blur doesn''t say impressionism to me.', '2007-09-10 09:47:21.000000', NULL, 1),
(4078008, 580860, 23098, '<td valign="top">This is very nice. I like the impressionistic work.  If the top were cropped to show just the birds, just a tad less of sky or only the birds and rocks it would be better still for me.  8</td>', 'This is very nice. I like the impressionistic work.  If the top were cropped to show just the birds, just a tad less of sky or only the birds and rocks it would be better still for me.  8', '2007-09-10 12:51:46.000000', NULL, 1),
(4078287, 583086, 64403, '<td valign="top">Subject matter, lighting, composition, effects - all add up to the perfect impressionistic image. It''s beautiful! You earn a 10 from me.</td>', 'Subject matter, lighting, composition, effects - all add up to the perfect impressionistic image. It''s beautiful! You earn a 10 from me.', '2007-09-10 14:54:05.000000', NULL, 1),
