(4079436, 582609, 73250, '<td valign="top">Nicely composed and the effect has been applied well. I wish the woman with the yellow bag...didn''t have the yellow bag...it''s a bit distracting. At the very least, tone it down a tad.</td>', 'Nicely composed and the effect has been applied well. I wish the woman with the yellow bag...didn''t have the yellow bag...it''s a bit distracting. At the very least, tone it down a tad.', '2007-09-10 22:24:34.000000', NULL, 1),
(4079441, 581382, 73250, '<td valign="top">I really like the composition and the colors of this shot. The effect has been done well.</td>', 'I really like the composition and the colors of this shot. The effect has been done well.', '2007-09-10 22:25:13.000000', NULL, 1),
(4079446, 581101, 73250, '<td valign="top">This is a lovely still life...the components are perfect. Very impressionistic.</td>', 'This is a lovely still life...the components are perfect. Very impressionistic.', '2007-09-10 22:26:33.000000', NULL, 1),
