(4079807, 580541, 60862, '<td valign="top">You''ve certainly reduced the objects to their essence.  Nice!</td>', 'You''ve certainly reduced the objects to their essence.  Nice!', '2007-09-11 00:40:52.000000', NULL, 1),
(4079997, 583232, 33672, '<td valign="top">Perfect example of the theme and photo.</td>', 'Perfect example of the theme and photo.', '2007-09-11 01:40:31.000000', NULL, 1),
