(4080427, 583086, 80058, '<td valign="top">Very nice</td>', 'Very nice', '2007-09-11 08:23:30.000000', NULL, 1),
(4080429, 583098, 80058, '<td valign="top">The effect you used is very good, interesting keeps making me look closely. Great choice of subject too! Well done</td>', 'The effect you used is very good, interesting keeps making me look closely. Great choice of subject too! Well done', '2007-09-11 08:25:06.000000', NULL, 1),
(4080434, 582957, 80058, '<td valign="top">Yes I like this, works for me =)</td>', 'Yes I like this, works for me =)', '2007-09-11 08:27:21.000000', NULL, 1),
(4080437, 583060, 80058, '<td valign="top">Maybe tooo much effects on it,altho its under the advanced editing I would still have liked to get a sense of photography on it, but I love the image works brilliantly. Hope it does well!</td>', 'Maybe tooo much effects on it,altho its under the advanced editing I would still have liked to get a sense of photography on it, but I love the image works brilliantly. Hope it does well!', '2007-09-11 08:29:24.000000', NULL, 1),
(4080440, 583232, 80058, '<td valign="top">Very nice,  love your choice of subject and composition, colours also works well for me! Well done and good luck! =)</td>', 'Very nice,  love your choice of subject and composition, colours also works well for me! Well done and good luck! =)', '2007-09-11 08:31:38.000000', NULL, 1),
(4080443, 582403, 80058, '<td valign="top">Hmmmmmm you could''ve taken advantage that this challenge was under advanced editing!</td>', 'Hmmmmmm you could''ve taken advantage that this challenge was under advanced editing!', '2007-09-11 08:32:54.000000', NULL, 1),
(4080452, 581023, 80058, '<td valign="top">Wow this is very different from the others, I love the composition you used here its spot on or me! The lady with the hat and umbrella made this shot, nice use of effects as well really gives a painterly feel in to it and yet I still get a sense that its a photograph, which some of the otheres entries don''t and being a photography challenge I wanted to see more of! Good luck!</td>', 'Wow this is very different from the others, I love the composition you used here its spot on or me! The lady with the hat and umbrella made this shot, nice use of effects as well really gives a painterly feel in to it and yet I still get a sense that its a photograph, which some of the otheres entries don''t and being a photography challenge I wanted to see more of! Good luck!', '2007-09-11 08:36:08.000000', NULL, 1),
(4080461, 579626, 80058, '<td valign="top">Ohhhh I am very intrigued to know how you achieved this! Stunning, a great still life. Seems like you sprayed a mirror with water to distort and reflect the subject??! Love it! Hope it gets top 10!!</td>', 'Ohhhh I am very intrigued to know how you achieved this! Stunning, a great still life. Seems like you sprayed a mirror with water to distort and reflect the subject??! Love it! Hope it gets top 10!!', '2007-09-11 08:39:07.000000', NULL, 1),
(4080471, 583236, 80058, '<td valign="top">Love this! Nice and simple, really captured my eyes, because I can''t make it out what it is the more it makes me look at it. Great feeling to it, altho I don''t get a sense that this is a photograph, not sure what voters are looking for but yes. Very nice =)</td>', 'Love this! Nice and simple, really captured my eyes, because I can''t make it out what it is the more it makes me look at it. Great feeling to it, altho I don''t get a sense that this is a photograph, not sure what voters are looking for but yes. Very nice =)', '2007-09-11 08:41:57.000000', NULL, 1),
(4080478, 582789, 80058, '<td valign="top">I like the coulours here, I think the scenery suits it very well. Great stuff well done =)</td>', 'I like the coulours here, I think the scenery suits it very well. Great stuff well done =)', '2007-09-11 08:46:50.000000', NULL, 1),
(4080482, 580998, 80058, '<td valign="top">Feels like a modern outtake on the challenge, I think it works well</td>', 'Feels like a modern outtake on the challenge, I think it works well', '2007-09-11 08:50:33.000000', NULL, 1),
(4080490, 582906, 80058, '<td valign="top">Oh I like the subjects! Its way different from the rest =) I like the fact it looks like an impressionist painting, but at te same time I also looks like a photograph! Love it! Would be a 10 from me if I could vote lol</td>', 'Oh I like the subjects! Its way different from the rest =) I like the fact it looks like an impressionist painting, but at te same time I also looks like a photograph! Love it! Would be a 10 from me if I could vote lol', '2007-09-11 08:53:28.000000', NULL, 1),
(4080493, 583282, 80058, '<td valign="top">Wow you really went for it with the  visible brush strokes! I like the subject you used, think colors are fab too, other people might find it too dark? Good luck tho!</td>', 'Wow you really went for it with the  visible brush strokes! I like the subject you used, think colors are fab too, other people might find it too dark? Good luck tho!', '2007-09-11 08:55:50.000000', NULL, 1),
(4080496, 583097, 80058, '<td valign="top">Lovely</td>', 'Lovely', '2007-09-11 08:56:44.000000', NULL, 1),
