(4081611, 582604, 14476, '<td valign="top">Reminds me of Cezanne.  Nice.</td>', 'Reminds me of Cezanne.  Nice.', '2007-09-11 16:51:55.000000', NULL, 1),
(4081900, 583098, 50695, '<td valign="top">If this effect was done with something other than a photoshop filter, let me know and I''ll bump your score up.</td>', 'If this effect was done with something other than a photoshop filter, let me know and I''ll bump your score up.', '2007-09-11 18:51:43.000000', NULL, 1),
(4082395, 581300, 80542, '<td valign="top">Absolutely breathtaking.  Nice work.</td>', 'Absolutely breathtaking.  Nice work.', '2007-09-11 22:30:50.000000', NULL, 1),
(4082398, 583206, 80542, '<td valign="top">Nice effects.  Looks like you used the natural sunlight to your total advantage.</td>', 'Nice effects.  Looks like you used the natural sunlight to your total advantage.', '2007-09-11 22:32:33.000000', NULL, 1),
(4082400, 580994, 80542, '<td valign="top">Perfect title.  This is gorgeous!</td>', 'Perfect title.  This is gorgeous!', '2007-09-11 22:33:12.000000', NULL, 1),
