(4082408, 583344, 74979, '<td valign="top">not a fan of this effect here doesn''t really fit the challenge; i think if you had left original colors it would have been more on the mark, especially this image of park, springtime, trees, romantic little bench...<br/> <br/>on relook, i''ve softened a bit, and you''re score goes up a tad...:)</td>', 'not a fan of this effect here doesn''t really fit the challenge; i think if you had left original colors it would have been more on the mark, especially this image of park, springtime, trees, romantic little bench... on relook, i''ve softened a bit, and you''re score goes up a tad...:)', '2007-09-11 22:36:17.000000', NULL, 1),
(4082410, 582971, 74979, '<td valign="top">lovely colors and image</td>', 'lovely colors and image', '2007-09-11 22:36:37.000000', NULL, 1),
(4082411, 580558, 74979, '<td valign="top">simply done, nice!</td>', 'simply done, nice!', '2007-09-11 22:36:54.000000', NULL, 1),
