(4082413, 582924, 80542, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2007-09-11 22:37:17.000000', NULL, 1),
(4082414, 580926, 80542, '<td valign="top">Nice angle and good depths in the colors.</td>', 'Nice angle and good depths in the colors.', '2007-09-11 22:37:50.000000', NULL, 1),
(4082415, 580860, 74979, '<td valign="top">love the blur action here, and the smooth water, sailboat...wish I was there!</td>', 'love the blur action here, and the smooth water, sailboat...wish I was there!', '2007-09-11 22:38:02.000000', NULL, 1),
(4082416, 582425, 80542, '<td valign="top">Whoa!  Life imitating art!</td>', 'Whoa!  Life imitating art!', '2007-09-11 22:38:18.000000', NULL, 1),
