(4086322, 580362, 50695, '<td valign="top">Yes, this has the right qualities of light and color. And it looks like most of the work was done in camera. Well done.</td>', 'Yes, this has the right qualities of light and color. And it looks like most of the work was done in camera. Well done.', '2007-09-13 00:31:25.000000', NULL, 1),
(4086326, 581620, 50695, '<td valign="top">This is perhaps the grave marker of a sparrow, unnoticed amidst the busy-ness and false perspective of <i>Dejeuner Sur L''Herbe</i>. After all, the girl is dead, the poet is dead, the language is dead. We have only these strange symbols of light spattering the canvas.</td>', 'This is perhaps the grave marker of a sparrow, unnoticed amidst the busy-ness and false perspective of Dejeuner Sur L''Herbe. After all, the girl is dead, the poet is dead, the language is dead. We have only these strange symbols of light spattering the canvas.', '2007-09-13 00:32:02.000000', NULL, 1),
(4086338, 583148, 50695, '<td valign="top">I give you a 7 for avoiding photoshop filters.</td>', 'I give you a 7 for avoiding photoshop filters.', '2007-09-13 00:34:00.000000', NULL, 1),
