(4088204, 582921, 70270, '<td valign="top">Monet would be proud ... Manet too for that matter.  9</td>', 'Monet would be proud ... Manet too for that matter.  9', '2007-09-13 20:57:07.000000', NULL, 1),
(4088208, 580408, 70270, '<td valign="top">Nice subject and good choice of a filter to create a nice impressionistic feeling.  Well done.</td>', 'Nice subject and good choice of a filter to create a nice impressionistic feeling.  Well done.', '2007-09-13 20:57:39.000000', NULL, 1),
(4088210, 583204, 70270, '<td valign="top">Perfect subject for the challenge, and I like how you''ve blurred the vegetation to show off the colors, forms and light.  9</td>', 'Perfect subject for the challenge, and I like how you''ve blurred the vegetation to show off the colors, forms and light.  9', '2007-09-13 20:58:15.000000', NULL, 1);
