(4089344, 582084, 35545, '<td valign="top">Yes, this isn''t pretty enough for a challenge.  I agree with <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=53147" rel="nofollow" target="_blank">Timfythetoo</a> about it being depressing but fascinating.  At first I thought I was looking at a monastery or a jail!  Good blur and color -- you really do have the feel of a painting.<br/> <br/>Nice work.</td>', 'Yes, this isn''t pretty enough for a challenge.  I agree with  Timfythetoo about it being depressing but fascinating.  At first I thought I was looking at a monastery or a jail!  Good blur and color -- you really do have the feel of a painting. Nice work.', '2007-09-14 10:12:46.000000', NULL, 0),
(4089349, 581300, 42100, '<td valign="top">Very nice still life Marac...congratulations on the HM!</td>', 'Very nice still life Marac...congratulations on the HM!', '2007-09-14 10:14:52.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4089351, 583204, 42100, '<td valign="top">Beautiful setting and photograph Catherine...congratulations on the HM!<br/><br/><i>Message edited by author 2007-09-14 09:16:55.</i></td>', 'Beautiful setting and photograph Catherine...congratulations on the HM!', '2007-09-14 10:16:19.000000', '2007-09-14 10:16:55.000000', 0),
(4089367, 582084, 12253, '<td valign="top">The 4.86 is highway robbery.  I demand a recount!  Seriously, this has more creative, REAL, impressionistic feel than most of the photos that are "impressionism wannabes" in the challenge.</td>', 'The 4.86 is highway robbery.  I demand a recount!  Seriously, this has more creative, REAL, impressionistic feel than most of the photos that are "impressionism wannabes" in the challenge.', '2007-09-14 10:30:35.000000', NULL, 0),
(4089368, 582956, 3087, '<td valign="top">I love the fact that you have so successfully nailed the theme without resorting to the use of filters in post-processing. Don''t get me wrong, I''m not criticising those who have used such filters, but I''m full of extra admiration and delight at the creativity and beauty of your image, which uses none.</td>', 'I love the fact that you have so successfully nailed the theme without resorting to the use of filters in post-processing. Don''t get me wrong, I''m not criticising those who have used such filters, but I''m full of extra admiration and delight at the creativity and beauty of your image, which uses none.', '2007-09-14 10:30:37.000000', NULL, 0),
(4089371, 582092, 10985, '<td valign="top">This should have won. It is absolutely lovely. Simple and effective. A strong impression it makes on me!</td>', 'This should have won. It is absolutely lovely. Simple and effective. A strong impression it makes on me!', '2007-09-14 10:31:40.000000', NULL, 0),
(4089372, 581300, 50551, '<td valign="top">Well, it was as good as you said! Nice study and a well deserved score.<br/><br/><i>Message edited by author 2007-09-14 09:32:25.</i></td>', 'Well, it was as good as you said! Nice study and a well deserved score.', '2007-09-14 10:32:11.000000', '2007-09-14 10:32:25.000000', 0),
(4089374, 581300, 3087, '<td valign="top">Great image, Marac and absolutely perfectly executed.</td>', 'Great image, Marac and absolutely perfectly executed.', '2007-09-14 10:32:40.000000', NULL, 0),
