(4089645, 581845, 40718, '<td valign="top">Well Gordon, I give you full and utter props for sticking it out.</td>', 'Well Gordon, I give you full and utter props for sticking it out.', '2007-09-14 12:04:56.000000', NULL, 0),
(4089673, 581300, 56744, '<td valign="top">I''m impressed with the highest quality of this image. One of the best photos Ive seen since Im here at DPC. Quality, technique, composition, mood, all at top stage. <b>Simply a fine piece of art</b>.<br/>Congrats Marac!</td>', 'I''m impressed with the highest quality of this image. One of the best photos Ive seen since Im here at DPC. Quality, technique, composition, mood, all at top stage. Simply a fine piece of art.Congrats Marac!', '2007-09-14 12:09:47.000000', NULL, 0),
